<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';Security::start();Security::requireRole(['reviewer','admin','super_admin']);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Software Submission Review · TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f6f8fb;color:#1f2937}.wrap{max-width:1200px;margin:auto;padding:28px}.head{display:flex;justify-content:space-between;gap:16px;align-items:center}.filters,.actions{display:flex;gap:8px;flex-wrap:wrap}.card{background:#fff;border:1px solid #dde5ec;border-radius:14px;padding:16px;margin-top:12px}.grid{display:grid;grid-template-columns:360px 1fr;gap:18px;margin-top:18px}.item{padding:12px;border:1px solid #e5e7eb;border-radius:10px;margin-bottom:8px;cursor:pointer}.item:hover{background:#f8fafc}.muted{color:#64748b;font-size:12px}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#edf2f7;font-size:11px}.warn{color:#9a3412}.detail dl{display:grid;grid-template-columns:180px 1fr;gap:8px 14px}.detail dt{font-weight:700}.detail dd{margin:0}.btn{padding:9px 12px;border:0;border-radius:9px;background:#123b67;color:#fff;cursor:pointer}.btn.secondary{background:#475569}.btn.danger{background:#b91c1c}input,select,textarea{padding:9px;border:1px solid #cbd5e1;border-radius:8px}textarea{width:100%;min-height:90px;box-sizing:border-box}@media(max-width:850px){.grid{grid-template-columns:1fr}.head{display:block}}</style></head><body><div class="wrap"><div class="head"><div><h1>Software Submission Review</h1><div class="muted">Review public suggestions and vendor submissions before any draft product is created.</div></div><a href="/admin">Admin</a></div><div class="card filters"><select id="status"><option value="">All statuses</option><option>new</option><option>duplicate_detected</option><option>under_review</option><option>needs_information</option><option>approved_for_draft</option><option>rejected</option><option>published</option></select><input id="q" placeholder="Search product, vendor, email"><button class="btn" id="load">Search</button></div><div class="grid"><div id="list"></div><div id="detail" class="card detail">Select a submission.</div></div></div><script>const csrf=<?php echo json_encode($csrf);?>;let current=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function load(){let u='/api/software-submission-admin?status='+encodeURIComponent(status.value)+'&q='+encodeURIComponent(q.value);let d=await fetch(u).then(r=>r.json());list.innerHTML=(d.items||[]).map(x=>`<div class="item" onclick="show(${x.id})"><b>${esc(x.product_name)}</b><div class="muted">${esc(x.vendor_name||'User suggestion')} · ${esc(x.status)} · ${esc(x.created_at)}</div>${x.duplicate_reason?`<div class="warn">Duplicate: ${esc(x.duplicate_reason)}</div>`:''}</div>`).join('')||'<div class="card">No submissions.</div>'}async function show(id){current=id;let d=await fetch('/api/software-submission-admin/'+id).then(r=>r.json()),s=d.submission;detail.innerHTML=`<h2>${esc(s.product_name)}</h2><div class="pill">${esc(s.status)}</div><dl><dt>Type</dt><dd>${esc(s.submission_type)}</dd><dt>Vendor</dt><dd>${esc(s.vendor_name||'—')}</dd><dt>Email</dt><dd>${esc(s.submitter_email||'—')}</dd><dt>Category</dt><dd>${esc(s.category_name||'—')}</dd><dt>Website</dt><dd>${s.official_website?`<a target="_blank" href="${esc(s.official_website)}">${esc(s.official_website)}</a>`:'—'}</dd><dt>Description</dt><dd>${esc(s.short_description||'—')}</dd><dt>Evidence</dt><dd>${esc(s.supporting_notes||'—')}</dd><dt>Duplicate</dt><dd>${esc(s.duplicate_reason||'None')}</dd><dt>Existing product</dt><dd>${esc(s.existing_product_name||'—')}</dd><dt>Created draft</dt><dd>${esc(s.created_product_name||'—')}</dd></dl><textarea id="notes" placeholder="Reviewer notes / clarification / rejection reason"></textarea><div class="actions"><button class="btn secondary" onclick="act('start_review')">Start review</button><button class="btn secondary" onclick="act('request_information')">Request info</button><button class="btn" onclick="act('approve_for_draft')">Approve to draft</button><button class="btn danger" onclick="act('reject')">Reject</button></div><h3>Link to existing product</h3><div class="actions"><input id="productId" type="number" placeholder="Product ID"><button class="btn secondary" onclick="act('link_existing',{product_id:Number(productId.value)})">Link existing</button></div><h3>History</h3>${(d.history||[]).map(h=>`<div class="item"><b>${esc(h.action)}</b> · ${esc(h.from_status||'—')} → ${esc(h.to_status)}<div class="muted">${esc(h.reviewer_name||'')} · ${esc(h.created_at)}</div><div>${esc(h.notes||'')}</div></div>`).join('')||'<div class="muted">No review history yet.</div>'}`;}async function act(action,extra={}){if(!current)return;let r=await fetch('/api/software-submission-admin/'+current+'/action',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({action,notes:document.getElementById('notes')?.value||'',...extra})});let d=await r.json();if(!r.ok){alert(d.error||'Action failed');return;}await show(current);await load();}load.onclick=load;load();</script></body></html>